// Derive the correct factorization by construction.
// BF = sum_b P(E|C,b) P(b|C) / sum_b P(E|!C,b) P(b|!C)
// let a=P(E|C,b), b=P(E|!C,b), u=P(b|C), v=P(b|!C), rho=a/b, tau=u/v
//   numerator  = sum a*u = sum (b*rho)*(v*tau) = sum b*v*rho*tau
//   denominator= sum b*v
//   => BF = sum_b w_b * rho_b * tau_b ,  w_b = b*v / sum(b*v)
const mk = () => {
  const k = 1 + Math.floor(Math.random()*5);
  const a=[],b=[],u=[],v=[];
  for(let i=0;i<k;i++){a.push(Math.random());b.push(Math.random());u.push(Math.random());v.push(Math.random());}
  const su=u.reduce((x,y)=>x+y,0), sv=v.reduce((x,y)=>x+y,0);
  for(let i=0;i<k;i++){u[i]/=su;v[i]/=sv;}
  return {a,b,u,v};
};
let worst=0;
for(let t=0;t<200000;t++){
  const {a,b,u,v}=mk();
  const BF = a.reduce((s,x,i)=>s+x*u[i],0)/b.reduce((s,x,i)=>s+x*v[i],0);
  const W = b.reduce((s,x,i)=>s+x*v[i],0);
  const w = b.map((x,i)=>x*v[i]/W);
  const rho = a.map((x,i)=>x/b[i]);
  const tau = u.map((x,i)=>x/v[i]);
  const BF2 = rho.reduce((s,r,i)=>s+w[i]*r*tau[i],0);      // <-- rho*tau
  const BF1 = rho.reduce((s,r,i)=>s+w[i]*r,0);              // my original (wrong) claim
  worst=Math.max(worst,Math.abs(BF-BF2));
  if(Math.abs(BF-BF1)>0.05 && t<3) console.log("wrong-claim sample BF",BF.toFixed(6),"BF1",BF1.toFixed(6));
}
console.log("max |BF - <rho*tau>| over 200k random families:", worst);
// consequences
let c1=0,c2=0,c3=0;
for(let t=0;t<200000;t++){
  const {a,b,u,v}=mk();
  const rho=a.map((x,i)=>x/b[i]), tau=u.map((x,i)=>x/v[i]);
  const W=b.reduce((s,x,i)=>s+x*v[i],0), w=b.map((x,i)=>x*v[i]/W);
  const BF=rho.reduce((s,r,i)=>s+w[i]*r*tau[i],0);
  if(rho.every(r=>Math.abs(r-1)<1e-12)) { // rho==1 => BF = <tau>
    c1 = Math.max(c1, Math.abs(BF - tau.reduce((s,r,i)=>s+w[i]*r,0)));
  }
  if(tau.every(r=>Math.abs(r-1)<1e-12)) {  // tau==1 => BF = <rho>
    c2 = Math.max(c2, Math.abs(BF - rho.reduce((s,r,i)=>s+w[i]*r,0)));
  }
  if(rho.every(r=>Math.abs(r-1)<1e-12)&&tau.every(r=>Math.abs(r-1)<1e-12)) {
    c3 = Math.max(c3, Math.abs(BF-1));
  }
}
