/* =====================================================================
   6. TABLE 3 — parse this document's own markdown and re-tally
   ===================================================================== */
(function table3() {
  const rows = [];
  for (const ln of lines) {
    const m = ln.match(/^\|\s*([^|]+?)\s*\|\s*([^|]*?)\s*\|\s*(\d+)\s*\|\s*(\d+)\s*\|\s*\*\*(\d+)\*\*\s*\|\s*$/);
