    if (!ln.startsWith('| A')) continue;
    const cells = ln.split('|').map(s => s.trim()).filter(Boolean);
    if (cells.length !== 8) continue;          // id | arg | E | Etag | B | Btag | note | verdict
    rows.push({ id: cells[0], e: cells[2], etag: cells[3], btag: cells[5] });
