   8. FORMULAS AND CROSS-REFERENCES actually present in the artifact
   ===================================================================== */
(function formulas() {
  const f = [
    'BF = r · P(¬b|H)',
    'BF(H : E) = P(E|H)/P(E|¬H)',
    'P(E|H,b) = 0',
    'P(E|H,¬b) = q·r',
