   10. ARITHMETIC CLAIMS MADE IN PROSE
   ===================================================================== */
(function prose() {
  // §2.3: deviation |BF - BF_naive| = r*P(!b|H), max 1.0
  let maxBF = 0;
  for (let t = 0; t < 200000; t++) maxBF = Math.max(maxBF, rnd() * rnd());
